# Creating a Custom REST Service in Dynamics 365 Finance & Operations (X++)

Here's a complete example of creating a custom REST service in Dynamics 365 F&O using X++.

## Step 1: Create a Data Contract Class

```xpp
[DataContractAttribute]
public class CustomerDataContract
{
    private str customerAccount;
    private str customerName;
    private str customerGroup;
    private str currency;
    private str email;
    private str phone;

    [DataMemberAttribute("CustomerAccount")]
    public str parmCustomerAccount(str _customerAccount = customerAccount)
    {
        customerAccount = _customerAccount;
        return customerAccount;
    }

    [DataMemberAttribute("CustomerName")]
    public str parmCustomerName(str _customerName = customerName)
    {
        customerName = _customerName;
        return customerName;
    }

    [DataMemberAttribute("CustomerGroup")]
    public str parmCustomerGroup(str _customerGroup = customerGroup)
    {
        customerGroup = _customerGroup;
        return customerGroup;
    }

    [DataMemberAttribute("Currency")]
    public str parmCurrency(str _currency = currency)
    {
        currency = _currency;
        return currency;
    }

    [DataMemberAttribute("Email")]
    public str parmEmail(str _email = email)
    {
        email = _email;
        return email;
    }

    [DataMemberAttribute("Phone")]
    public str parmPhone(str _phone = phone)
    {
        phone = _phone;
        return phone;
    }
}
```

## Step 2: Create the Service Class

```xpp
class CustomerRESTService
{
    /// <summary>
    /// Gets customer details by account number
    /// </summary>
    /// <param name = "_customerAccount">Customer account number</param>
    /// <returns>Customer data contract</returns>
    [SysEntryPointAttribute(true)]
    public CustomerDataContract getCustomer(str _customerAccount)
    {
        CustomerDataContract contract = new CustomerDataContract();
        CustTable           custTable;
        DirPartyTable       dirPartyTable;

        select firstonly custTable
            where custTable.AccountNum == _customerAccount;

        if (custTable.RecId)
        {
            select firstonly dirPartyTable
                where dirPartyTable.RecId == custTable.Party;

            contract.parmCustomerAccount(custTable.AccountNum);
            contract.parmCustomerName(dirPartyTable.Name);
            contract.parmCustomerGroup(custTable.CustGroup);
            contract.parmCurrency(custTable.Currency);
        }

        return contract;
    }

    /// <summary>
    /// Creates a new customer
    /// </summary>
    /// <param name = "_contract">Customer data contract</param>
    /// <returns>Created customer account number</returns>
    [SysEntryPointAttribute(true)]
    public str createCustomer(CustomerDataContract _contract)
    {
        CustTable           custTable;
        NumberSeq           numberSeq;
        str                 customerAccount;

        ttsbegin;

        // Get next account number from number sequence
        numberSeq = NumberSeq::newGetNum(CustParameters::numRefCustAccount());
        customerAccount = numberSeq.num();

        custTable.clear();
        custTable.AccountNum    = customerAccount;
        custTable.CustGroup     = _contract.parmCustomerGroup();
        custTable.Currency      = _contract.parmCurrency();

        // Initialize party
        custTable.initFromCustGroup(CustGroup::find(_contract.parmCustomerGroup()));

        if (custTable.validateWrite())
        {
            custTable.insert();
            numberSeq.used();
        }
        else
        {
            throw error("Customer validation failed.");
        }

        ttscommit;

        return customerAccount;
    }

    /// <summary>
    /// Gets a list of all customers
    /// </summary>
    /// <returns>List of customer data contracts</returns>
    [SysEntryPointAttribute(true)]
    public List getAllCustomers()
    {
        List                    customerList = new List(Types::Class);
        CustTable               custTable;
        DirPartyTable           dirPartyTable;
        CustomerDataContract    contract;

        while select custTable
            join dirPartyTable
            where dirPartyTable.RecId == custTable.Party
        {
            contract = new CustomerDataContract();
            contract.parmCustomerAccount(custTable.AccountNum);
            contract.parmCustomerName(dirPartyTable.Name);
            contract.parmCustomerGroup(custTable.CustGroup);
            contract.parmCurrency(custTable.Currency);

            customerList.addEnd(contract);
        }

        return customerList;
    }

    /// <summary>
    /// Updates an existing customer
    /// </summary>
    [SysEntryPointAttribute(true)]
    public boolean updateCustomer(CustomerDataContract _contract)
    {
        CustTable custTable;
        boolean   success = false;

        ttsbegin;

        select forupdate custTable
            where custTable.AccountNum == _contract.parmCustomerAccount();

        if (custTable.RecId)
        {
            custTable.CustGroup = _contract.parmCustomerGroup();
            custTable.Currency  = _contract.parmCurrency();

            if (custTable.validateWrite())
            {
                custTable.update();
                success = true;
            }
        }

        ttscommit;

        return success;
    }
}
```

## Step 3: Create the Service Definition

In Visual Studio, add a new **Service** item:

```xpp
// Service Properties:
// Name: CustomerService
// Class: CustomerRESTService
// Namespace: YourCompany.Services
```

Add the service operations through the designer:
- `getCustomer`
- `createCustomer`
- `getAllCustomers`
- `updateCustomer`

## Step 4: Create the Service Group

Create a new **Service Group** item:

```xpp
// Service Group Properties:
// Name: CustomerServiceGroup
// AutoDeploy: Yes
// Description: Customer REST Service Group
```

Add the `CustomerService` to the Service Group.

## Step 5: Calling the REST Service

The service is automatically exposed at:
```
https://[YourD365URL]/api/services/CustomerServiceGroup/CustomerService/getCustomer
```

### Example C# Client Call:

```csharp
// Request body (JSON)
{
    "_customerAccount": "US-001"
}

// POST to:
// https://[YourD365URL]/api/services/CustomerServiceGroup/CustomerService/getCustomer
// Authorization: Bearer [AccessToken]
// Content-Type: application/json
```

### Example Authentication (OAuth 2.0):

```csharp
public async Task<string> GetAccessToken()
{
    var client = new HttpClient();
    var values = new Dictionary<string, string>
    {
        { "grant_type", "client_credentials" },
        { "client_id", "your-client-id" },
        { "client_secret", "your-client-secret" },
        { "resource", "https://yourd365url.dynamics.com" }
    };

    var content = new FormUrlEncodedContent(values);
    var response = await client.PostAsync(
        "https://login.microsoftonline.com/[tenant-id]/oauth2/token", 
        content);

    var responseString = await response.Content.ReadAsStringAsync();
    // Parse JSON to get access_token
    return responseString;
}
```

## Key Points to Remember

1. **`[SysEntryPointAttribute(true)]`** - Marks methods as service entry points and enables authorization checks
2. **`[DataContractAttribute]`** - Defines a serializable contract class
3. **`[DataMemberAttribute]`** - Marks properties for serialization
4. **Service Group** - Required to expose services as REST endpoints
5. **Authentication** - All service calls require OAuth 2.0 bearer token
6. **AutoDeploy** - Must be set to `Yes` on the service group

## Testing with Postman

```http
POST https://[YourD365URL]/api/services/CustomerServiceGroup/CustomerService/getCustomer
Authorization: Bearer [your-access-token]
Content-Type: application/json

{
    "_customerAccount": "US-001"
}
```

This creates a fully functional custom REST service that can be consumed by external applications.

